// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.registryimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.BrainSkillimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singletonimport kotlin.reflect.KClass/** * NOUS — Skill registry. * * Collects all [BrainSkill] implementations via Hilt multibinding. Skills are * auto-discovered at app startup — feature modules contribute their skills * via `@Binds @IntoSet` in their Hilt modules. * * Three types of skills (per spec §6 Layer 2): *   1. Built-in skills (CallSkill, SmsSkill, OpenAppSkill, ...) — compiled in *   2. JSON-based skills (declarative, no code) — stored in Room *   3. JS skills (QuickJS sandbox, sideload only) — stored in Room * * For Module 2, only source #1 (Hilt multibinding) is wired. Sources #2 and #3 * are added when :feature:selfmodify (Module 13) ships. * * @see <a href="docs/spec/module2-spec-review.pdf">§6 Layer 2</a> */@Singletonclass SkillRegistry @Inject constructor(    /** Built-in skills from Hilt multibinding. */    private val compiledSkills: Set<@JvmSuppressWildcards BrainSkill>,) {    @Volatile    private var cachedSkills: List<BrainSkill>? = null    /** User-defined skills (JSON + JS, added dynamically — empty for Module 2). */    @Volatile    private var userSkills: List<BrainSkill> = emptyList()    /**     * Get all active skills.     */    fun getAllSkills(): List<BrainSkill> {        cachedSkills?.let { return it }        val all: List<BrainSkill> = compiledSkills.toList() + userSkills        cachedSkills = all        Timber.tag("NOUS.L2").v("SkillRegistry: ${all.size} skills (${compiledSkills.size} compiled, ${userSkills.size} user)")        return all    }    /**     * Find skills that handle a given [intentType].     */    fun findSkillsForIntent(intentType: KClass<out Intent>): List<BrainSkill> {        return getAllSkills().filter { skill ->            skill.supportedIntents.contains(intentType)        }    }    /**     * Find a skill by ID.     */    fun findById(skillId: String): BrainSkill? {        return getAllSkills().firstOrNull { it.id == skillId }    }    /**     * Find skills that require a specific permission.     */    fun findSkillsRequiringPermission(permission: String): List<BrainSkill> {        return getAllSkills().filter { permission in it.requiredPermissions }    }    /**     * Add a user skill dynamically (JSON or JS skill from Module 13).     * If a skill with the same ID exists, it is replaced.     */    fun addUserSkill(skill: BrainSkill) {        userSkills = userSkills.filterNot { it.id == skill.id } + skill        cachedSkills = null        Timber.tag("NOUS.L2").i("User skill added: ${skill.id}")    }    /**     * Remove a user skill by ID.     */    fun removeUserSkill(skillId: String): Boolean {        val before = userSkills.size        userSkills = userSkills.filterNot { it.id == skillId }        val removed = userSkills.size < before        if (removed) {            cachedSkills = null            Timber.tag("NOUS.L2").i("User skill removed: $skillId")        }        return removed    }    /** Total skill count (for debugging). */    fun count(): Int = getAllSkills().size    /** Refresh cache (called when user skills change in Room). */    fun refresh() {        cachedSkills = null    }}
// THREAD_FIX_005
// Skill Registry - Thread-safe skill lookups